#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import itertools
import json
import random
from dataclasses import dataclass

Clause = tuple[int, ...]
CNF = tuple[Clause, ...]
Equation = tuple[int, int]
Assignment = dict[int, bool]

SCHEMA = "janus.cross_language_negotiation.v1.1"
POLICY = "PAIRWISE_HORN_EQUALITY_BASIS_V1"


def canonical_json(value) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def digest(value) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()


def normalize(formula: CNF) -> CNF:
    clauses: list[Clause] = []
    for clause in formula:
        literals = set(clause)
        if any(-literal in literals for literal in literals):
            continue
        canonical = tuple(sorted(literals, key=lambda x: (abs(x), x < 0)))
        if canonical not in clauses:
            clauses.append(canonical)
    clauses.sort(key=lambda clause: (len(clause), clause))
    kept: list[Clause] = []
    for clause in clauses:
        if any(set(previous) <= set(clause) for previous in kept):
            continue
        kept.append(clause)
    return tuple(kept)


def is_horn(formula: CNF) -> bool:
    return all(sum(literal > 0 for literal in clause) <= 1 for clause in formula)


def eval_clause(clause: Clause, assignment: Assignment) -> bool:
    return any(assignment[abs(literal)] == (literal > 0) for literal in clause)


def eval_cnf(formula: CNF, assignment: Assignment) -> bool:
    return all(eval_clause(clause, assignment) for clause in formula)


def eval_affine(rows: tuple[Equation, ...], assignment: Assignment) -> bool:
    for mask, rhs in rows:
        parity = 0
        for index in range(max(assignment, default=0)):
            if mask >> index & 1:
                parity ^= int(assignment[index + 1])
        if parity != rhs:
            return False
    return True


class BudgetExceeded(Exception):
    pass


@dataclass
class Meter:
    limit: int
    work_units: int = 0
    horn_calls: int = 0
    affine_calls: int = 0
    clause_scans: int = 0
    row_xors: int = 0
    equality_queries: int = 0
    literal_queries: int = 0

    def charge(self, amount: int = 1) -> None:
        self.work_units += amount
        if self.work_units > self.limit:
            raise BudgetExceeded


def merge_units(base: dict[int, bool], extra: dict[int, bool]):
    merged = dict(base)
    for variable, value in extra.items():
        if variable in merged and merged[variable] != value:
            return None
        merged[variable] = value
    return merged


def horn_solve(
    formula: CNF,
    variable_count: int,
    units: dict[int, bool],
    meter: Meter,
):
    meter.horn_calls += 1
    meter.charge()
    clauses = list(normalize(formula))
    clauses.extend(((variable,) if value else (-variable,)) for variable, value in sorted(units.items()))
    clauses = list(normalize(tuple(clauses)))
    if not is_horn(tuple(clauses)):
        return {"status": "OPEN_LANGUAGE"}

    assignment = {variable: False for variable in range(1, variable_count + 1)}
    trace: list[dict] = []
    changed = True
    while changed:
        changed = False
        for index, clause in enumerate(clauses):
            meter.clause_scans += 1
            meter.charge()
            positive = next((literal for literal in clause if literal > 0), None)
            body = [-literal for literal in clause if literal < 0]
            if all(assignment[variable] for variable in body):
                if positive is None:
                    return {
                        "status": "UNSAT",
                        "trace": trace + [{"op": "conflict", "clause": index}],
                        "units": {str(v): int(b) for v, b in sorted(units.items())},
                    }
                if not assignment[positive]:
                    assignment[positive] = True
                    trace.append({"op": "set", "var": positive, "clause": index})
                    changed = True

    if not eval_cnf(tuple(clauses), assignment):
        raise AssertionError("Horn least model failed source replay")
    return {
        "status": "SAT",
        "assignment": assignment,
        "trace": trace,
        "units": {str(v): int(b) for v, b in sorted(units.items())},
    }


def affine_solve(
    rows: tuple[Equation, ...],
    variable_count: int,
    units: dict[int, bool],
    meter: Meter,
):
    meter.affine_calls += 1
    meter.charge()

    extended: list[tuple[int, int, int]] = [
        (mask, rhs, 1 << index) for index, (mask, rhs) in enumerate(rows)
    ]
    base = len(extended)
    extended.extend(
        (1 << (variable - 1), int(value), 1 << (base + offset))
        for offset, (variable, value) in enumerate(sorted(units.items()))
    )

    basis: dict[int, tuple[int, int, int]] = {}
    row_ops: list[dict] = []
    for source_index, (mask, rhs, provenance) in enumerate(extended):
        while mask:
            pivot = (mask & -mask).bit_length() - 1
            if pivot not in basis:
                basis[pivot] = (mask, rhs, provenance)
                row_ops.append({"op": "pivot", "source": source_index, "var": pivot + 1})
                break
            other_mask, other_rhs, other_provenance = basis[pivot]
            mask ^= other_mask
            rhs ^= other_rhs
            provenance ^= other_provenance
            meter.row_xors += 1
            meter.charge()
            row_ops.append({"op": "xor", "source": source_index, "pivot": pivot + 1})
        if mask == 0 and rhs:
            return {
                "status": "UNSAT",
                "provenance": provenance,
                "row_ops": row_ops,
                "units": {str(v): int(b) for v, b in sorted(units.items())},
            }

    assignment = {variable: False for variable in range(1, variable_count + 1)}
    for pivot in sorted(basis, reverse=True):
        mask, rhs, _ = basis[pivot]
        value = rhs
        for index in range(variable_count):
            if index != pivot and (mask >> index) & 1:
                value ^= int(assignment[index + 1])
        assignment[pivot + 1] = bool(value)

    if not eval_affine(rows, assignment):
        raise AssertionError("affine model failed source replay")
    for variable, value in units.items():
        if assignment[variable] != value:
            raise AssertionError("affine model failed unit replay")
    return {
        "status": "SAT",
        "assignment": assignment,
        "row_ops": row_ops,
        "units": {str(v): int(b) for v, b in sorted(units.items())},
    }


def falsifying_units(clause: Clause) -> dict[int, bool]:
    return {abs(literal): literal < 0 for literal in clause}


def horn_entails_clause(
    formula: CNF,
    clause: Clause,
    variable_count: int,
    units: dict[int, bool],
    meter: Meter,
):
    assumptions = merge_units(units, falsifying_units(clause))
    if assumptions is None:
        return {
            "entailed": True,
            "proof": {
                "status": "UNSAT",
                "reason": "INCONSISTENT_FALSIFYING_UNITS",
                "clause": list(clause),
            },
        }
    result = horn_solve(formula, variable_count, assumptions, meter)
    return {
        "entailed": result["status"] == "UNSAT",
        "proof": result,
    }


